solution.exercise.cpp:
#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
size_t flatten(const value *v, size_t n, int *out) {
    size_t k = 0;
    for (size_t i = 0; i < n; i++) {
        if (v[i].kind == INTEGER)
            out[k++] = v[i].integer;
        else if (v[i].kind == ARRAY)
            k += flatten(v[i].items, v[i].count, out + k);
    }
    return k;
}

tests.test_exercise.cpp:
#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdlib.h>
#include <string.h>
int main(void) {
    value a[] = {{INTEGER, 2, NULL, 0}, {NIL, 0, NULL, 0}, {INTEGER, 6, NULL, 0}};
    value b[] = {{INTEGER, 1, NULL, 0},
                 {ARRAY, 0, a, 3},
                 {NIL, 0, NULL, 0},
                 {INTEGER, 4, NULL, 0}};
    int o[10];
    assert(flatten(b, 4, o) == 4 && o[0] == 1 && o[1] == 2 && o[2] == 6 && o[3] == 4);
    assert(flatten(NULL, 0, o) == 0);
    return 0;
}
